use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

/// Extracts the imaginary parts from a vector of complex numbers `(real, imag)`.
/// 
/// Specification:
/// - The result vector has the same length as the input.
/// - For every valid index `i`, `res[i] == val[i].1`.
/// - In particular, if `val[i].1 == 0.0` then `res[i] == 0.0`.
/// - And if `(val[i].0 != 0.0 || val[i].1 != 0.0)`, then `res[i] == val[i].1`.
fn imag(val: Vec<(f64, f64)>) -> (res: Vec<f64>)
    ensures
        // same length
        res@.len() == val@.len(),
        // each entry is the imaginary part
        forall |i: nat| i < val@.len() ==> res@.index(i) == val@.index(i).1,
        // if the imaginary part is zero, the output is zero
        forall |i: nat| i < val@.len() && val@.index(i).1 == 0.0
                     ==> res@.index(i) == 0.0,
        // if the complex number is nonzero, output equals the imaginary part
        forall |i: nat| i < val@.len() 
                     && (val@.index(i).0 != 0.0 || val@.index(i).1 != 0.0)
                     ==> res@.index(i) == val@.index(i).1,
{
    let mut res: Vec<f64> = Vec::new();
    let mut i: usize = 0;
    // build `res` by pushing each imaginary component in order
    while i < val.len()
        invariant
            // loop index within bounds
            i <= val.len(),
            // we've pushed exactly `i` elements so far
            res.len() == i,
            // and for all j < i, res[j] == val[j].1
            forall |j: nat| j < i
                         ==> res@.index(j) == val@.index(j).1,
        decreases
            // ensure termination
            val.len() - i,
    {
        // extract the i-th complex number
        let (_re, im) = val[i];
        // push its imaginary part
        res.push(im);
        i += 1;
    }
    res
}

} // verus!    

